('o6-C3-4', 'q6000005-0000-0000-0000-000000000003', '<input>', 10, 'Tepat! Elemen <input> menerima masukan data dari pengguna (teks, email, password, dll.).'),
('o6-C4-1', 'q6000005-0000-0000-0000-000000000004', '<btn>', 0, 'Keliru. btn umumnya hanya nama class CSS, bukan tag HTML.'),
('o6-C4-2', 'q6000005-0000-0000-0000-000000000004', '<button>', 10, 'Tepat! Tag <button> mendefinisikan tombol yang dapat diklik pengguna.'),
('o6-C4-3', 'q6000005-0000-0000-0000-000000000004', '<click>', 0, 'Keliru. Tidak ada tag <click> dalam HTML.'),
('o6-C4-4', 'q6000005-0000-0000-0000-000000000004', '<submitbtn>', 0, 'Keliru. Tidak ada tag <submitbtn> dalam HTML.'),
('o6-C5-1', 'q6000005-0000-0000-0000-000000000005', 'Mempercepat server', 0, 'Keliru. Tag semantik berkaitan dengan struktur dokumen di klien, bukan kecepatan server.'),
('o6-C5-2', 'q6000005-0000-0000-0000-000000000005', 'Memberikan makna pada struktur halaman', 10, 'Tepat! HTML semantik memberi arti jelas pada setiap bagian halaman bagi browser, mesin pencari (SEO), dan screen reader.'),
('o6-C5-3', 'q6000005-0000-0000-0000-000000000005', 'Menggantikan CSS', 0, 'Keliru. Styling tetap ditangani oleh CSS.'),
('o6-C5-4', 'q6000005-0000-0000-0000-000000000005', 'Menggantikan JavaScript', 0, 'Keliru. Interaktivitas dinamis tetap membutuhkan JavaScript.'),
('o6-C6-1', 'q6000005-0000-0000-0000-000000000006', '<div>', 0, 'Keliru. <div> adalah container non-semantik.'),
('o6-C6-2', 'q6000005-0000-0000-0000-000000000006', '<span>', 0, 'Keliru. <span> adalah pembungkus inline non-semantik.'),
('o6-C6-3', 'q6000005-0000-0000-0000-000000000006', '<article>', 10, 'Tepat! <article> adalah tag semantik HTML5 yang merepresentasikan konten mandiri.'),
('o6-C6-4', 'q6000005-0000-0000-0000-000000000006', '<font>', 0, 'Keliru. <font> adalah tag presentasional usang (deprecated) di HTML4.'),
('o6-C7-1', 'q6000005-0000-0000-0000-000000000007', 'Bagian awal halaman atau section', 10, 'Tepat! Tag <header> menandai area pengantar atau navigasi di bagian atas halaman/section.'),
('o6-C7-2', 'q6000005-0000-0000-0000-000000000007', 'Menampilkan gambar', 0, 'Keliru. Menampilkan gambar menggunakan tag <img>.'),
('o6-C7-3', 'q6000005-0000-0000-0000-000000000007', 'Menyimpan data', 0, 'Keliru. <header> adalah elemen struktur semantik.'),
('o6-C7-4', 'q6000005-0000-0000-0000-000000000007', 'Membuat form', 0, 'Keliru. Membuat form menggunakan tag <form>.'),
('o6-C8-1', 'q6000005-0000-0000-0000-000000000008', 'Membuat hyperlink', 0, 'Keliru. Hyperlink dibuat dengan tag <a>.'),
('o6-C8-2', 'q6000005-0000-0000-0000-000000000008', 'Wadah atau container umum', 10, 'Tepat! <div> digunakan sebagai wadah pengelompokan elemen secara umum untuk styling layout.'),
('o6-C8-3', 'q6000005-0000-0000-0000-000000000008', 'Membuat tabel', 0, 'Keliru. Tabel dibuat dengan tag <table>.'),
('o6-C8-4', 'q6000005-0000-0000-0000-000000000008', 'Membuat heading', 0, 'Keliru. Heading dibuat dengan tag <h1>–<h6>.'),
('o6-C9-1', 'q6000005-0000-0000-0000-000000000009', 'Tidak menutup tag', 0, 'Keliru. Tag berpasangan harus ditutup rapi agar struktur DOM tidak rusak.'),
('o6-C9-2', 'q6000005-0000-0000-0000-000000000009', 'Menulis semua kode dalam satu baris', 0, 'Keliru. Menulis semua kode dalam satu baris menyulitkan pembacaan dan debugging.'),
('o6-C9-3', 'q6000005-0000-0000-0000-000000000009', 'Menggunakan indentasi yang rapi', 10, 'Tepat! Indentasi konsisten mempermudah pembacaan hierarki elemen dan pemeliharaan kode.'),
('o6-C9-4', 'q6000005-0000-0000-0000-000000000009', 'Menghapus atribut penting', 0, 'Keliru. Atribut penting seperti alt, href, dan lang wajib dipertahankan.'),
('o6-C10-1', 'q6000005-0000-0000-0000-000000000010', 'HTML untuk struktur, CSS untuk tampilan, JavaScript untuk interaksi', 10, 'Tepat! Ketiganya saling melengkapi: HTML membangun kerangka struktur, CSS mempercantik tampilan, dan JavaScript mengatur logika interaktif.'),
('o6-C10-2', 'q6000005-0000-0000-0000-000000000010', 'HTML untuk tampilan, CSS untuk database, JavaScript untuk server', 0, 'Keliru. Peran HTML dan CSS tertukar, serta CSS bukan untuk database.'),
('o6-C10-3', 'q6000005-0000-0000-0000-000000000010', 'HTML untuk backend, CSS untuk frontend, JavaScript untuk database', 0, 'Keliru. HTML dan CSS berjalan di sisi klien (frontend).'),
('o6-C10-4', 'q6000005-0000-0000-0000-000000000010', 'Semua salah', 0, 'Keliru. Pilihan pertama menjelaskan pembagian peran yang benar.');
